<script lang="ts">
  import { onMount } from 'svelte';
  import { workspaces } from '$lib/stores/app';
  import { ListChecks, ArrowUpRight, Copy, Download, Upload, Check, Circle, AlertCircle, Play, Save, Plus, Monitor, Globe, Search, ChevronRight } from '@lucide/svelte';
  import seed from '$lib/chatgpt-tasks/ddt-plan.json';
  import { STORAGE_KEY, validatePlan, promptFor, nextReady, waitingFor, transition, type TaskPlan, type ChatTask } from '$lib/chatgpt-tasks/model';
  import { copyText, nativeAvailable } from '$lib/taskdock/api';
  import { openUrl } from '$lib/api/app-info';
  import { invoke } from '@tauri-apps/api/core';
  let plan = $state<TaskPlan | null>(null), selectedId = $state('T01'), query = $state(''), notice = $state(''), error = $state('');
  let receipt = $state(''), conversationUrl = $state(''), importInput: HTMLInputElement;
  let client = $state<'desktop'|'web'>('desktop'), busy = $state(false), inspection = $state('尚未检查客户端'), windowRef = $state('');
  let preparedId = $state('');
  let autoStatus=$state('尚未启用'),queueRoot=$state(''),autoBatchId=$state(''),queueWorkspace=$state('win-wsl-ddt-dba9e3bb800f49fb'),webFallback=$state(true),autoBusy=$state(false);
  async function queueAction(action:'start'|'status'|'pause'|'resume'|'stop'|'submit') {
    if(!nativeAvailable()){error='独立调度器需要 Windows GPTBridge 桌面应用；此预览不会启动或发送。';return;}
    if(!plan)return;
    if(action==='submit' && autoBatchId){error='当前计划已有批次编号；请查看原批次状态，不重复提交。';return;}
    if(action==='submit' && plan.tasks.some(t=>t.status!=='draft')){error='只能提交未派发的草稿计划，不能重交已发送或未知任务。';return;}
    autoBusy=true;
    try {
      const batchId=action==='submit'?crypto.randomUUID():autoBatchId;
      const batch=action==='submit'?{schemaVersion:1,connector:'GPTBridge Windows',batchId,title:plan.title,tasks:plan.tasks.map(t=>({id:t.id,title:t.title,dependsOn:t.dependsOn,prompt:promptFor(plan!,t)}))}:null;
      const result=await invoke<any>('chatgpt_queue_control',{request:{action,workspaceId:queueWorkspace,client,model:plan.requestedModel,effort:plan.requestedEffort,webFallback,batch}});
      if(action==='submit'){autoBatchId=batchId;localStorage.setItem(STORAGE_KEY+':batch',batchId);notice='任务批次已提交到独立队列；由用户已启用的 Windows 调度器处理。';}
      if(!autoBatchId && result.pending){const matches=result.pending.filter((b:any)=>b.title===plan!.title&&JSON.stringify(b.taskIds)===JSON.stringify(plan!.tasks.map(t=>t.id)));if(matches.length===1){autoBatchId=matches[0].batchId;localStorage.setItem(STORAGE_KEY+':batch',autoBatchId);}}
      if(result.queueRoot)queueRoot=result.queueRoot;
      if(result.scheduler){autoStatus=result.scheduler.status+(result.scheduler.detail?' · '+result.scheduler.detail:'');
        const current=result.batches?.find((b:any)=>b.batchId===autoBatchId);
        if(current){for(const task of plan.tasks){const row=current.tasks?.[task.id];if(!row)continue;task.status=row.status==='completed'?'done':row.status==='blocked'?'blocked':row.status==='sent'?'sent':'unknown';task.receipt=`独立调度回执：${row.detail??row.status}；请求=${row.requestId??''}；结果=${row.receiptPath??''}`;}persist(validatePlan(plan));}
      } else autoStatus=result.status??'状态未知';
    }catch(e){error=String(e);}finally{autoBusy=false;}
  }
  const selected = $derived(plan?.tasks.find(t=>t.id===selectedId));
  const shown = $derived(plan?.tasks.filter(t=>(t.title+t.version+t.id).toLowerCase().includes(query.toLowerCase())) ?? []);
  const done = $derived(plan?.tasks.filter(t=>t.status==='done').length ?? 0);
  const next = $derived(plan ? nextReady(plan) : undefined);
  const labels: Record<string,string> = {draft:'待派发',sent:'已发送 · 待验收',unknown:'结果未知',done:'已验收',blocked:'有阻塞'};
  onMount(()=>{
    try { autoBatchId=localStorage.getItem(STORAGE_KEY+':batch')??'';const raw=localStorage.getItem(STORAGE_KEY);if(raw) plan=validatePlan(JSON.parse(raw)); }
    catch(e){error='本地任务包读取失败，已保留原记录。请导出或导入有效任务包后继续：'+String(e);}
    const timer=setInterval(()=>{if(nativeAvailable()&&plan&&!autoBusy)void queueAction('status');},5000);return()=>clearInterval(timer);
  });
  function persist(nextPlan: TaskPlan) {
    try { localStorage.setItem(STORAGE_KEY,JSON.stringify(nextPlan));plan=nextPlan;error=''; }
    catch(e){error='未保存，请先导出任务包：'+String(e);}
  }
  function choose(task: ChatTask) { selectedId=task.id;receipt=task.receipt;conversationUrl=task.conversationUrl;preparedId=''; }
  function loadSeed() {
    if(plan && !confirm('用弹弹堂 20 个草稿替换当前任务包？请先导出需要保留的记录。')) return;
    autoBatchId='';localStorage.removeItem(STORAGE_KEY+':batch');persist(validatePlan(seed)); selectedId='T01';receipt='';conversationUrl='';notice='已载入三份正式交接对应的 20 个任务草稿，尚未派发。';
  }
  function saveTask() {
    if(!plan || !selected) return;
    try { persist(validatePlan(plan));notice='已保存任务内容。';preparedId=''; } catch(e) {error=String(e);}
  }
  function record(status: 'sent'|'done'|'unknown'|'blocked') {
    if(!plan || !selected) return;
    try { persist(transition(plan,selected.id,status,receipt,conversationUrl));notice='已保存人工核对状态。'; }
    catch(e){error=String(e);}
  }
  async function copyPrompt() {
    if(!plan || !selected) return;
    try{await copyText(promptFor(plan,selected));notice='提示词已复制；发送前在 ChatGPT 中核对模型和 GPTBridge Windows。';}catch(e){error=String(e);}
  }
  async function openChat() {
    try { if(nativeAvailable()) await openUrl('https://chatgpt.com/');else window.open('https://chatgpt.com/','_blank','noopener,noreferrer'); }
    catch(e){error=String(e);}
  }
  function download() {
    if(!plan) return;
    const blob=new Blob([JSON.stringify(validatePlan(plan),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
    a.href=url;a.download='gptbridge-chatgpt-tasks.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
  async function importPlan(event: Event) {
    const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;
    try { if(file.size>2*1024*1024)throw new Error('任务包不能超过 2 MB。');const nextPlan=validatePlan(JSON.parse(await file.text()));if(plan && !confirm('导入会替换当前任务包，是否继续？'))return;autoBatchId='';localStorage.removeItem(STORAGE_KEY+':batch');persist(nextPlan);choose(nextPlan.tasks[0]);notice='任务包已导入，状态按原记录保留。'; }
    catch(e){error=String(e);}finally{input.value='';}
  }
  async function dispatch(action:'inspect'|'stage'|'send') {
    if(!nativeAvailable()){error='客户端自动化需要 Windows GPTBridge 桌面应用；浏览器预览仅支持任务编辑、导入导出和手动派发。';return;}
    if(!plan || !selected || busy)return;
    if(action!=='inspect' && (selected.status!=='draft' || waitingFor(plan,selected).length)){error='当前任务不是依赖已完成的草稿，不能派发。';return;}
    busy=true;error='';
    try {
      const result=await invoke<{status:string;detail:string;windowRef?:string;requestId?:string}>('chatgpt_task_dispatch',{request:{action,client,taskId:selected.id,requestId:action==='send'?preparedId:crypto.randomUUID(),windowRef,model:plan.requestedModel,effort:plan.requestedEffort,prompt:promptFor(plan,selected)}});
      inspection=result.detail;windowRef=result.windowRef??'';
      if(action==='stage' && result.status==='prepared')preparedId=result.requestId??'';
      if(action==='send'){
        const task=selected; task.status=result.status==='sent'?'sent':'unknown';task.receipt=`${result.detail}\n客户端=${client}；窗口=${result.windowRef??''}；请求=${result.requestId??preparedId}`;persist(validatePlan(plan));preparedId='';
      }
      if(result.status==='blocked')error=result.detail;else notice=result.detail;
    }catch(e){const message=String(e);if(action==='send'){selected.status='unknown';selected.receipt=`发送调用结果未知；请求=${preparedId}；查询原对话，不要重发。`;persist(validatePlan(plan));preparedId='';}error=message;}
    finally{busy=false;}
  }
</script>

<svelte:head><title>ChatGPT 任务工作台 · GPTBridge</title></svelte:head>
<div class="cq-page">
  <header class="cq-heading"><div><div class="cq-kicker">GPTBRIDGE / CHATGPT TASKS</div><h1>ChatGPT 任务工作台<span>新</span></h1><p>把一项大工作拆开，带着上下文逐个推进。</p></div><div class="cq-actions"><input bind:this={importInput} type="file" accept="application/json,.json" onchange={importPlan} hidden/><button onclick={()=>importInput.click()}><Upload size={15}/>导入任务包</button><button disabled={!plan} onclick={download}><Download size={15}/>导出</button><button class="cq-primary" onclick={loadSeed}><Plus size={15}/>载入弹弹堂 20 任务</button></div></header>
  {#if error}<div role="alert" class="cq-alert"><AlertCircle size={17}/><span>{error}</span><button onclick={()=>error=''} aria-label="关闭错误">×</button></div>{/if}
  {#if notice}<div role="status" class="cq-notice"><Check size={15}/>{notice}</div>{/if}
  <section class="cq-context"><div><span class="cq-dot"></span><strong>GPTBridge Windows</strong><span class="cq-tag">独立任务队列</span></div><span>本地保存 · {done} / {plan?.tasks.length??0} 已验收</span><div class="cq-progress" aria-label="任务完成进度"><i style={`width:${plan?done/plan.tasks.length*100:0}%`}></i></div></section>
  <section class="cq-auto"><div><div class="cq-kicker">WINDOWS / 独立自动调度</div><h2>交代一次，按回执自动推进</h2><p>Codex 只提交队列；调度器操作 ChatGPT，只有 ChatGPT 调用 GPTBridge Windows。</p></div><div class="cq-auto-controls"><label>运行项目<select aria-label="自动调度项目" bind:value={queueWorkspace}>{#each $workspaces as workspace}<option value={workspace.id}>{workspace.name}</option>{/each}{#if !$workspaces.length}<option value="win-wsl-ddt-dba9e3bb800f49fb">Windows · 弹弹堂开发全集（待原生连接）</option>{/if}</select></label><label class="cq-toggle"><input type="checkbox" bind:checked={webFallback}/>桌面准备失败且未发送时回落网页</label><div class="cq-actions"><button class="cq-primary" disabled={!plan||autoBusy||!!autoBatchId} onclick={()=>queueAction('submit')}><Plus size={14}/>提交整批到队列</button><button disabled={!plan||autoBusy} onclick={()=>queueAction('start')}><Play size={14}/>启用独立调度器</button><button disabled={!plan||autoBusy} onclick={()=>queueAction('pause')}>暂停</button><button disabled={!plan||autoBusy} onclick={()=>queueAction('resume')}>继续</button><button disabled={!plan||autoBusy} onclick={()=>queueAction('stop')}>停止</button></div><small>状态：{autoStatus} {#if autoBatchId}· 批次 {autoBatchId.slice(0,8)}{/if}</small>{#if queueRoot}<code>{queueRoot}</code>{/if}</div></section>
  <div class="cq-layout">
    <aside class="cq-queue"><div class="cq-panel-title"><h2>任务队列</h2><span>{plan?.tasks.length??0}</span></div><label class="cq-search"><Search size={15}/><input aria-label="搜索任务" placeholder="搜索任务或版本…" bind:value={query}/></label><div class="cq-list">{#each shown as task (task.id)}<button class="cq-task" class:chosen={selectedId===task.id} onclick={()=>choose(task)}><div class="cq-task-top"><span class="cq-task-id">{task.id}</span><span class="cq-version">{task.version}</span></div><strong>{task.title}</strong><div class="cq-task-state" class:complete={task.status==='done'}>{#if task.status==='done'}<Check size={12}/>{:else if task.status==='unknown'}<AlertCircle size={12}/>{:else}<Circle size={10}/>{/if}{labels[task.status]}</div></button>{/each}{#if !shown.length}<div class="cq-empty-small">{plan?'没有匹配的任务。':'先载入 20 个任务，或导入自己的任务包。'}</div>{/if}</div><div class="cq-queue-bottom"><span>下一个可推进</span><button disabled={!next} onclick={()=>next&&choose(next)}>{next?.id??'—'} {next?.title??'等待任务'}<ChevronRight size={14}/></button></div></aside>
    <main class="cq-editor">{#if plan && selected}<div class="cq-editor-head"><div><span class="cq-task-id">{selected.id}</span><span class="cq-version">{selected.version}</span></div><button onclick={saveTask}><Save size={14}/>保存</button></div><input class="cq-title-input" aria-label="任务名称" bind:value={selected.title}/><label class="cq-field">本任务目标<textarea rows="3" bind:value={selected.goal}></textarea></label><div class="cq-dependencies"><span>前置任务</span>{#each selected.dependsOn as id}<button onclick={()=>{const t=plan?.tasks.find(t=>t.id===id);if(t)choose(t);}}>{id}<span>{plan.tasks.find(t=>t.id===id)?.status==='done'?'已验收':'待完成'}</span></button>{/each}{#if !selected.dependsOn.length}<small>无，可直接开始</small>{/if}</div><div class="cq-section-label"><h2>发送到 ChatGPT 的提示词</h2><button onclick={copyPrompt}><Copy size={14}/>复制完整提示词</button></div><textarea class="cq-prompt" aria-label="任务提示词" value={promptFor(plan,selected)} oninput={(e)=>{selected.customPrompt=e.currentTarget.value;preparedId='';}} spellcheck="false"></textarea><details class="cq-details"><summary>输入资料与验收要求</summary><h3>正式输入</h3>{#each selected.inputs as input}<code>{input}</code>{/each}<h3>本任务验收</h3><ul>{#each selected.acceptance as item}<li>{item}</li>{/each}</ul></details><section class="cq-receipt"><h2>执行回执</h2><label class="cq-field">ChatGPT 对话链接（网页端）<input placeholder="https://chatgpt.com/c/…" bind:value={conversationUrl}/></label><label class="cq-field">实际结果与证据<textarea rows="3" placeholder="记录产物路径、验证结果和未完成项。发送完成不等于任务验收通过。" bind:value={receipt}></textarea></label><div class="cq-actions"><button onclick={()=>record('sent')} disabled={selected.status!=='draft'}>登记手动发送</button><button onclick={()=>record('unknown')}>结果待核对</button><button onclick={()=>record('blocked')}>记录阻塞</button><button class="cq-primary" onclick={()=>record('done')}><Check size={14}/>验收完成</button></div></section>{:else}<div class="cq-empty"><ListChecks size={42}/><h2>先把工作拆成可执行的任务</h2><p>内置三条弹弹堂开发线的 20 个接续任务。每个任务都带正式输入、执行步骤、依赖和验收要求。</p><button class="cq-primary" onclick={loadSeed}>载入 20 个任务<ChevronRight size={16}/></button><small>任务以草稿保存，不会自动发送或启动旧任务。</small></div>{/if}</main>
    <aside class="cq-dispatch"><div class="cq-panel-title"><h2>ChatGPT 派发</h2><span class="cq-tag">Windows</span></div><fieldset><legend>发送目标</legend><button class:chosen={client==='desktop'} onclick={()=>{client='desktop';preparedId='';windowRef='';inspection='尚未检查桌面客户端';}}><Monitor size={18}/><div><strong>桌面客户端</strong><small>先核对左上角 ChatGPT 模式</small></div><span class="cq-radio"></span></button><button class:chosen={client==='web'} onclick={()=>{client='web';preparedId='';windowRef='';inspection='尚未检查网页';}}><Globe size={18}/><div><strong>ChatGPT 网页</strong><small>需要时手动切换</small></div><span class="cq-radio"></span></button></fieldset><label class="cq-field">模型偏好<select value={plan?.requestedModel??'GPT-6'} onchange={e=>{if(plan){plan.requestedModel=e.currentTarget.value;persist(plan);preparedId='';}}}><option>GPT-6</option><option>GPT-5.6 Sol</option></select></label><label class="cq-field">思考强度偏好<input value={plan?.requestedEffort??'Pro'} onchange={e=>{if(plan){plan.requestedEffort=e.currentTarget.value;persist(plan);preparedId='';}}}/><small>填写客户端实际显示的选项名称；不可用时停止。</small></label><div class="cq-client-state"><span class="cq-dot quiet"></span><strong>客户端状态</strong><p>{inspection}</p></div><button class="cq-wide" disabled={busy||!selected} onclick={()=>dispatch('inspect')}>检查客户端与选项</button><button class="cq-wide" disabled={busy||!selected||selected.status!=='draft'} onclick={()=>dispatch('stage')}><Copy size={15}/>填入当前任务，不发送</button><button class="cq-wide cq-primary" disabled={busy||!preparedId||!selected||selected.status!=='draft'} onclick={()=>dispatch('send')}><Play size={15}/>{busy?'正在处理…':'发送已核对任务'}</button><button class="cq-wide" onclick={openChat}>打开 ChatGPT 网页<ArrowUpRight size={15}/></button><p class="cq-help">先检查、填入并核对，再发送。遇到登录、选项缺失或不确定的发送结果会停止；切换客户端不会重发未知任务。</p><div class="cq-boundary"><strong>在聊天中继续开发</strong><p>任务准备时先切换并回读 ChatGPT 模式；发送前再核对。Codex 工作模式禁止调用 GPTBridge，Mac 连接保持独立。</p></div></aside>
  </div>
</div>

<style>
